'use strict';
// Presentation-only state. No API calls, file reads, filesystem writes or model calls.
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const INITIAL=[{id:'b1',name:'课堂数据完整备份',time:'2026-11-01 09:20',size:'1.26 GB',type:'手动备份',valid:true},{id:'b2',name:'十月教学数据',time:'2026-10-28 17:35',size:'1.18 GB',type:'手动备份',valid:true},{id:'b3',name:'学期初安全快照',time:'2026-10-01 08:10',size:'864 MB',type:'恢复前快照',valid:true}];
const DATA=[['课程与学生','6 门课程 · 238 名单人次','6 门 / 238 人次','6 门 / 238 人次'],['课堂记录','42 场签到与答题','42 场','38 场'],['作业与批改','12 份作业 · 含原始附件','12 份','10 份'],['PPT课件与模板','18 份课件 · 4 个模板','18 / 4','16 / 4'],['教案与模板','10 份教案 · 3 个模板','10 / 3','8 / 3'],['问卷与答卷','8 份问卷 · 426 份答卷','8 / 426','7 / 382']];
let records=INITIAL.map(x=>({...x})),selected=null,step=0,mode='normal',operation=null,percent=0,stage='',checked=false,checkComplete=false,result=null,unmount=null,timer=null,toastTimer=null,opEpoch=0;
const pill=(s,c='green')=>`<span class="pill ${c}">${s}</span>`;
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p class="caption">${sub}</p></div>${action}</div>${body}</section>`;}
function progress(){return `<div class="progress" role="status"><div class="progress-top"><span>${stage}</span><b>${percent}%</b></div><div class="track" role="progressbar" aria-label="模拟操作进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}"><i style="width:${percent}%"></i></div><small>模拟进度 · 不会操作真实文件</small></div>`;}
function home(){const rows=mode==='empty'?[]:records,last=rows[0];return `<div class="stats"><div class="stat hero"><div class="stat-label">最近成功备份 <span class="stat-icon">▣</span></div><strong>${last?last.time:'尚未创建备份'}</strong><small>${last?'完整教学数据 · '+last.size:'先创建一份完整备份，保留当前教学资料'}</small></div><div class="stat"><div class="stat-label">当前教学数据 <span class="stat-icon">▤</span></div><strong>1.32 <span style="font-size:12px;font-weight:400">GB</span></strong><small>6 门课程 · 含附件、课件和模板 · 示例</small></div><div class="stat"><div class="stat-label">备份条件 <span class="stat-icon">◷</span></div><strong>${mode==='busy'?'有任务进行中':'可以创建备份'}</strong><small>${mode==='busy'?'1 场签到、1 份问卷回收中 · 示例':'当前无进行中的教学任务 · 示例'}</small></div></div><div class="layout"><div class="left">${panel('创建完整备份','一次保存教学数据及其对应附件',`<div class="scope">${DATA.map((x,i)=>`<div class="scope-item"><span>${['☰','◷','✓','▧','✎','▤'][i]}</span><div><b>${x[0]}</b><small>${x[1]}</small></div></div>`).join('')}</div><div class="notice">包含教学设置、历史版本及原始附件。不会迁移 WorkBuddy 登录态、外部软件或本机专用路径。</div>${mode==='busy'?'<div class="notice warn" style="margin-top:10px">签到与问卷回收正在进行。请先回到相应模块完成任务，本页不会自动结束课堂。</div>':''}${operation==='backup'?progress():''}${result==='backup-fail'?'<div class="notice error" style="margin-top:12px">模拟：备份位置空间不足，未创建成功记录。当前教学数据未改变，可检查空间后重试。</div>':''}<div class="row-actions"><small>备份保存到独立位置，避免与教学数据放在一起</small><button class="primary" data-action="backup" ${operation?'disabled':''}>${operation==='backup'?'正在创建…':'创建完整备份'}</button></div>`,pill('推荐'))}${panel('备份记录','只将已完成并校验的备份登记为成功',rows.length?table(['备份','容量','状态','操作'],rows.map(r=>[`<span class="record-title">${esc(r.name)}</span><small>${r.time} · ${r.type}</small>`,r.size,pill('校验通过'),`<button class="link" data-action="details" data-id="${r.id}">查看</button><button class="link" data-action="download" data-id="${r.id}">下载</button><button class="link" data-action="record-restore" data-id="${r.id}" ${operation?'disabled':''}>恢复</button>`])):'<div class="empty">还没有备份记录。创建第一份完整备份后，会在这里显示。</div>')} </div><div class="right">${panel('从备份恢复','需要找回数据，或迁移到另一台电脑',`<div class="restore-box"><div class="restore-icon">↶</div><h3>先检查，再恢复</h3><p>查看备份内容和版本，再确认替换。恢复前会先保留当前数据，恢复失败可回滚。</p><button data-action="start-restore" ${operation?'disabled':''}>选择备份文件 →</button></div><div class="notice warn" style="margin-top:15px">整体恢复将替换当前教学数据并重启平台。首版不合并两份数据。</div>`)}${panel('存储位置','教学数据与备份分开保存',`<div class="storage-row"><span>当前教学数据</span><b>1.32 GB</b></div><div class="capacity"><i style="width:44%;background:#718bd1"></i><i style="width:27%;background:#80b7ae"></i><i style="width:19%;background:#af9ed2"></i><i style="width:10%;background:#d7bf8d"></i></div>${[['PPT与模板','580 MB','#718bd1'],['作业与批改附件','356 MB','#80b7ae'],['教案与参考资料','251 MB','#af9ed2'],['名单、记录及其他','133 MB','#d7bf8d']].map(x=>`<div class="storage-row"><i style="--c:${x[2]}"></i><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}<div class="path"><code title="示例位置">D:\\一堂课\\data</code><button class="link" data-action="copy-path">复制</button></div><div class="storage-row" style="margin-top:10px"><span>备份位置</span><b>D:\\教学备份</b></div><button class="link" data-action="open-folder" style="margin-top:6px">查看文件夹 ↗</button>`)} </div></div>`;}
function steps(){return `<nav class="steps" aria-label="恢复步骤">${['选择备份','检查内容','确认恢复','恢复结果'].map((n,i)=>`${i?'<span class="connector"></span>':''}<div class="step ${step===i+1?'on':step>i+1?'done':''}" ${step===i+1?'aria-current="step"':''}><b>${step>i+1?'✓':i+1}</b>${n}</div>`).join('')}</nav>`;}
function fileInfo(){return `<div class="file-info"><span>▣</span><div><b>${esc(selected?.name||'未选择文件')}</b><small>${esc(selected?.size||'')} · ${selected?.source==='local'?'仅选择文件，未读取内容':'虚构示例备份'}</small></div>${pill('格式 v1','')}</div>`;}
function actionRow(left,right){return `<div class="step-actions"><button data-action="${left[0]}" ${operation?'disabled':''}>← ${left[1]}</button><div>${right}</div></div>`;}
function uploadPage(){return panel('选择要恢复的备份','只接受平台完整备份包，普通Excel、CSV或PPT不能用来恢复平台',`<div id="upload" class="upload-wrapper"></div><p class="inline-error" id="uploadError" role="alert"></p><div class="sample-action"><span>还没有备份文件？</span><button class="link" data-action="sample">使用示例备份体验</button></div>${selected?fileInfo():''}<div class="notice" style="margin-top:17px">原型仅显示所选文件的名称与大小，不读取或上传文件内容。后续“检查结果”为演示，不代表真实文件通过校验。</div>${actionRow(['home','返回备份首页'],`<button class="primary" data-action="check" ${!selected?'disabled':''}>下一步：检查内容 →</button>`)}`);}
function checkPage(){const invalid=mode==='invalid';return panel('检查备份内容','先了解这份备份包含什么，检查不会修改当前数据',`${fileInfo()}${operation==='check'?progress():''}${checkComplete?`<div class="notice ${invalid?'error':''}">${invalid?'模拟检查未通过：发现附件校验值不一致，不能继续恢复。请选择其他备份，当前数据未改变。':'模拟检查完成：包结构、版本和文件完整性符合演示要求。实际实现将逐项读取并验证。'}</div><div class="check-list">${[['备份格式与应用版本','支持恢复'],['文件路径与解压范围','符合要求'],['教学数据结构与关联','符合要求'],['附件完整性',invalid?'校验不一致':'符合要求'],['目标磁盘可用空间','足够']].map((x,i)=>`<div class="check-item ${invalid&&i===3?'bad':''}"><span>${invalid&&i===3?'!':'✓'}</span>${x[0]}<small>${x[1]} · 模拟</small></div>`).join('')}</div>${invalid?'':table(['数据范围','备份中包含'],DATA.map(x=>[x[0],x[1]]))}`:''}${actionRow(['upload','重新选择备份'],`<button class="primary" data-action="confirm-page" ${!checkComplete||invalid?'disabled':''}>下一步：确认恢复 →</button>`)}`);}
function confirmPage(){const busy=mode==='busy';return panel('确认恢复范围','请对比备份与当前数据，确认后再开始',`${fileInfo()}<div class="notice warn">将用备份中的内容整体替换当前数据，不合并。恢复前先创建一份当前数据安全快照，完成后重启平台；WorkBuddy需在目标电脑重新核对连接。</div><div class="comparison" style="margin-top:17px">${table(['数据范围','当前数据','恢复后的数据'],DATA.map(x=>[x[0],x[3],`<span class="changed">${x[2]}</span>`]))}</div><div class="check-list"><div class="check-item ${busy?'bad':''}"><span>${busy?'!':'✓'}</span>活动任务检测<small>${busy?'签到与问卷仍在进行 · 阻止恢复':'无进行中任务 · 模拟'}</small></div><div class="check-item"><span>✓</span>恢复前安全快照<small>创建成功后，才开始替换</small></div></div>${busy?'<div class="notice error">示例课堂与问卷还未结束。请先处理活动任务，不能直接恢复；平台不会代替老师停止它们。</div>':''}<label class="check-label"><input id="ack" type="checkbox" ${checked?'checked':''} ${busy?'disabled':''}>我已知晓将整体替换当前教学数据，并重启平台。</label>${actionRow(['check-back','返回检查内容'],`<button class="danger" data-action="ask-restore" ${!checked||busy?'disabled':''}>恢复这份备份</button>`)}`);}
function resultPage(){const failed=result==='restore-fail';return panel(operation==='restore'?'正在模拟恢复':'恢复结果','当前为交互演示，不会真正替换文件或重启服务',operation==='restore'?`<div class="result"><div class="result-icon">↶</div><h2>正在恢复教学数据</h2><p>请勿关闭此演示流程。正式版会保存恢复事务状态，重新启动后仍能查看结果。</p></div>${progress()}${actionRow(['home','返回备份首页'],'<button disabled>恢复中…</button>')}`:`<div class="result"><div class="result-icon ${failed?'fail':''}">${failed?'!':'✓'}</div><h2>${failed?'恢复未完成，已回滚':'恢复完成'}</h2><p>${failed?'模拟：数据替换后启动检查未通过，已回到恢复前的数据。安全快照仍保留，可检查备份后重试。':'模拟：教学数据及附件已恢复，平台已重新启动。历史生成任务不会自动重跑，请核对课程与资源。'}</p></div><div class="result-timeline">${[['恢复前安全快照','已保留'],['备份内容验证','通过'],['数据替换',failed?'已撤回':'完成'],['平台重新启动',failed?'原数据可用':'检查通过']].map(x=>`<div><span>✓</span>${x[0]}<small>${x[1]} · 模拟</small></div>`).join('')}</div><div class="notice ${failed?'warn':''}" style="margin-top:18px">${failed?'原有数据保持可用，不需要再次执行恢复来“撤销”。':'恢复后请核对课程名单、附件及WorkBuddy配置；旧签到二维码失效，后台制作不会自动继续。'}</div>${actionRow([failed?'upload':'home',failed?'重新选择备份':'返回备份首页'],`<button class="primary" data-action="home">${failed?'返回当前数据':'查看恢复后的概况'}</button>`)}`);}
function render(){unmount?.();unmount=null;$('#scenario').disabled=!!operation;$('#view').innerHTML=step?`<div class="workflow">${steps()}${[null,uploadPage,checkPage,confirmPage,resultPage][step]()}</div>`:home();if(step===1)mountUpload();const ack=$('#ack');if(ack)ack.onchange=()=>{checked=ack.checked;const b=$('[data-action="ask-restore"]');b.disabled=!checked||mode==='busy';};}
function mountUpload(){if(!window.InclassUpload){$('#uploadError').textContent='本机上传组件未加载，请刷新后重试。';return;}unmount=window.InclassUpload.mount($('#upload'),{accept:'.zip',multiple:false,limit:1,label:'将平台备份包拖到此处，或',types:'ZIP · 原型仅显示文件名称与大小，不上传或读取内容',exceedText:'一次选择一份备份，请先移除当前文件。',files:selected?[{uid:1,name:selected.name,status:'success'}]:[],getFiles:()=>selected?[{uid:1,name:selected.name,status:'success'}]:[],onSelect:files=>{const f=files[0];if(!f||!f.size||!/\.zip$/i.test(f.name)){ $('#uploadError').textContent='请选择一份非空的ZIP备份文件。';return;}selected={name:f.name,size:(f.size/1048576).toFixed(1)+' MB',source:'local'};checked=false;checkComplete=false;render();},onRemove:()=>{selected=null;checked=false;checkComplete=false;render();},onError:message=>{$('#uploadError').textContent=message;}});}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3000);}
function dialog(title,body,actions){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#dialogActions').innerHTML=actions;$('#dialog').showModal();const safe=$('[data-action="close-dialog"]');if(safe)safe.focus();else $('#closeDialog').focus();}
function go(n){if(operation==='restore')return;step=n;render();window.scrollTo({top:0,behavior:'smooth'});}
function run(kind){clearInterval(timer);const epoch=++opEpoch;operation=kind;percent=0;checked=false;result=null;const phases=kind==='backup'?['正在模拟检查备份条件','正在模拟生成一致性快照','正在模拟收集数据与附件','正在模拟验证清单与文件','正在模拟保存备份包']:kind==='check'?['正在模拟读取备份清单','正在模拟校验版本与结构','正在模拟检查文件完整性','正在模拟核对目标空间']:['正在模拟创建恢复前安全快照','正在模拟准备恢复暂存目录','正在模拟替换教学数据','正在模拟启动平台与检查','正在模拟确认恢复结果'];stage=phases[0];if(kind==='restore')step=4;render();let tick=0;timer=setInterval(()=>{if(epoch!==opEpoch)return;tick++;percent=Math.min(100,Math.round(tick/phases.length*100));stage=phases[Math.min(tick,phases.length-1)];if(tick>=phases.length){clearInterval(timer);operation=null;if(kind==='backup'){if(mode==='backup-fail')result='backup-fail';else {if(mode==='empty'){records=[];mode='normal';$('#scenario').value='normal';}records.unshift({id:'new'+Date.now(),name:'课堂数据完整备份',time:new Date().toLocaleString('sv-SE').slice(0,16),size:'1.32 GB',type:'手动备份',valid:true});toast('模拟备份完成，已添加一条示例记录');}}else if(kind==='check')checkComplete=true;else {result=mode==='restore-fail'?'restore-fail':'success';records.unshift({id:'safety'+Date.now(),name:'恢复前安全快照',time:new Date().toLocaleString('sv-SE').slice(0,16),size:'1.32 GB',type:'恢复前快照',valid:true});}}render();},650);}
function record(id){return records.find(r=>r.id===id);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,r=record(b.dataset.id);if(operation&&a!=='close-dialog')return;
 if(a==='home'){result=null;go(0);}if(a==='backup'){if(mode==='busy'){toast('示例活动任务尚未结束，请先完成签到与问卷回收');return;}run('backup');}
 if(a==='start-restore'){selected=null;checkComplete=false;checked=false;go(1);}if(a==='sample'){selected={name:'一堂课_完整备份_2026-11-01.zip',size:'1.26 GB',source:'sample'};checked=false;checkComplete=false;render();}
 if(a==='upload'){checkComplete=false;go(1);}if(a==='check'&&selected){step=2;run('check');}if(a==='check-back'){go(2);}if(a==='confirm-page'&&checkComplete&&mode!=='invalid')go(3);
 if(a==='record-restore'&&r){selected={name:r.name+'.zip',size:r.size,source:'sample'};checkComplete=false;step=2;run('check');}
 if(a==='ask-restore'&&checked&&mode!=='busy')dialog('确认整体恢复教学数据？',`<p>将使用 <b>${esc(selected.name)}</b> 替换当前全部教学数据，不合并现有内容。</p><p>恢复前先创建安全快照，成功后才替换并重启平台；若恢复失败，回滚原数据。</p><div class="notice warn">本次仅模拟恢复，真实文件与平台服务不会发生变化。</div>`,'<button data-action="close-dialog">暂不恢复</button><button class="danger" data-action="restore">确认恢复并重启</button>');
 if(a==='restore'&&checked&&mode!=='busy'){ $('#dialog').close();run('restore');}
 if(a==='close-dialog')$('#dialog').close();
 if(a==='details'&&r)dialog(r.name,`<p>${r.time} · ${r.size} · 格式v1 · 示例应用版本</p>${table(['备份范围','内容'],DATA.map(x=>[x[0],x[1]]))}<div class="notice" style="margin-top:15px">所有内容与校验状态均为虚构示例，不代表已备份真实教学数据。</div>`,'<button data-action="close-dialog">返回</button>');
 if(a==='download'&&r)dialog('下载备份',`<p>正式版会下载包含教学附件的完整ZIP包。原型只提供一份明确标注的示例JSON清单，不生成可恢复备份。</p>`, '<button data-action="close-dialog">返回</button><button class="primary" data-action="download-example">下载示例清单</button>');
 if(a==='download-example'){const blob=new Blob([JSON.stringify({prototype:true,notRestorable:true,message:'虚构示例清单，不包含教学数据，不可用于恢复',contents:DATA.map(x=>({scope:x[0],example:x[1]}))},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='一堂课_原型示例清单_不可恢复.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#dialog').close();toast('已下载示例清单，不是可恢复的备份包');}
 if(a==='copy-path')toast('示例数据位置：D:\\一堂课\\data；原型未复制真实路径');if(a==='open-folder')toast('正式版将打开备份文件夹；原型不操作系统目录');
});
$('#closeDialog').onclick=()=>$('#dialog').close();$('#scenario').onchange=()=>{if(operation)return;mode=$('#scenario').value;records=INITIAL.map(x=>({...x}));selected=null;checked=false;checkComplete=false;result=null;step=0;render();};
window.addEventListener('beforeunload',()=>{clearInterval(timer);unmount?.();});render();
